import{_ as o,o as d,c as i,G as t}from"./chunks/framework.zCPgfX_8.js";const p=JSON.parse('{"title":"实施计划与阶段记录","description":"实施计划与阶段记录的完整学习记录，保留原笔记中的方法、示例与代码。","frontmatter":{"title":"实施计划与阶段记录","date":"2026-11-06","description":"实施计划与阶段记录的完整学习记录，保留原笔记中的方法、示例与代码。","category":"Java 后端","folder":"java/yukishopping","order":100,"sourceNote":"YukiShopping/实施计划.md","imported":true},"headers":[{"level":2,"title":"由岐商城后端实施计划","slug":"由岐商城后端实施计划","link":"#由岐商城后端实施计划","children":[{"level":3,"title":"一、现状盘点","slug":"一现状盘点","link":"#一现状盘点","children":[]},{"level":3,"title":"二、开工前问题清单（阶段 0 必须处理）","slug":"二开工前问题清单阶段-0-必须处理","link":"#二开工前问题清单阶段-0-必须处理","children":[]},{"level":3,"title":"三、分阶段实施计划","slug":"三分阶段实施计划","link":"#三分阶段实施计划","children":[{"level":4,"title":"阶段 0：基础设施补齐（约半天）","slug":"阶段-0基础设施补齐约半天","link":"#阶段-0基础设施补齐约半天","children":[]},{"level":4,"title":"阶段 1：用户与认证（约 1 天）","slug":"阶段-1用户与认证约-1-天","link":"#阶段-1用户与认证约-1-天","children":[]},{"level":4,"title":"阶段 2：商品浏览（约 1 天，全公开接口）","slug":"阶段-2商品浏览约-1-天全公开接口","link":"#阶段-2商品浏览约-1-天全公开接口","children":[]},{"level":4,"title":"阶段 3：购物车（约半天）","slug":"阶段-3购物车约半天","link":"#阶段-3购物车约半天","children":[]},{"level":4,"title":"阶段 4：订单与支付（约 2~3 天，核心难点）","slug":"阶段-4订单与支付约-23-天核心难点","link":"#阶段-4订单与支付约-23-天核心难点","children":[]},{"level":4,"title":"阶段 5：评价（约半天）","slug":"阶段-5评价约半天","link":"#阶段-5评价约半天","children":[]},{"level":4,"title":"阶段 6：管理端（约 1~2 天）","slug":"阶段-6管理端约-12-天","link":"#阶段-6管理端约-12-天","children":[]},{"level":4,"title":"阶段 7：验收与收尾","slug":"阶段-7验收与收尾","link":"#阶段-7验收与收尾","children":[]}]},{"level":3,"title":"四、验收清单 ↔ 阶段对照（来自接口文档第 6 节）","slug":"四验收清单-阶段对照来自接口文档第-6-节","link":"#四验收清单-阶段对照来自接口文档第-6-节","children":[]},{"level":3,"title":"五、约定与提醒","slug":"五约定与提醒","link":"#五约定与提醒","children":[]}]}],"relativePath":"posts/java/yukishopping/implementation-plan.md","filePath":"posts/java/yukishopping/implementation-plan.md"}'),l={name:"posts/java/yukishopping/implementation-plan.md"};function c(r,e,a,s,n,u){return d(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="实施计划与阶段记录" tabindex="-1">实施计划与阶段记录 <a class="header-anchor" href="#实施计划与阶段记录" aria-label="Permalink to &quot;实施计划与阶段记录&quot;">​</a></h1><blockquote><p>这是项目阶段文档，接口与实施状态按记录时的约定保留。</p></blockquote><blockquote><p><strong>迁移校订</strong></p><ul><li>保留原项目阶段计划及当时勾选状态；它们是历史记录，不表示对应功能已由本次迁移重新验收。依赖版本与缺口清单也需结合原项目版本阅读。</li></ul></blockquote><div><h2 id="由岐商城后端实施计划" tabindex="-1">由岐商城后端实施计划 <a class="header-anchor" href="#由岐商城后端实施计划" aria-label="Permalink to &quot;由岐商城后端实施计划&quot;">​</a></h2><blockquote><p>依据：<a href="/blog-pages/posts/java/yukishopping/api-reference.html">api接口库.md</a>（V1 接口规范）+ 01_schema.sql（<code>01_schema.sql</code>）（13 张表）+ 现有骨架代码盘点。 用法：按阶段顺序推进，每完成一项勾一项；每个阶段结束启动服务用真实请求回归一遍，不等最后统一测。 盘点日期：2026-09-05</p></blockquote><hr><h3 id="一现状盘点" tabindex="-1">一、现状盘点 <a class="header-anchor" href="#一现状盘点" aria-label="Permalink to &quot;一、现状盘点&quot;">​</a></h3><table tabindex="0"><thead><tr><th>部分</th><th>状态</th></tr></thead><tbody><tr><td>pom.xml</td><td>Java 17 + Spring Boot 3.3.5 + Web/Validation/Security + MyBatis-Plus 3.5.9 + MySQL + Lombok</td></tr><tr><td>application.yml</td><td>端口 8080，context-path <code>/api/v1</code>（与文档一致），MySQL 环境变量注入，Redis 配置存在但依赖未引入</td></tr><tr><td>公共层</td><td><code>ApiResponse</code>/<code>PageResult</code>/<code>BusinessException</code>/<code>GlobalExceptionHandler</code>/<code>SecurityConfig</code> 已就位</td></tr><tr><td>控制器</td><td>7 个控制器均为占位（返回空数据），请求体 record 与基础校验已搭好</td></tr><tr><td>业务层</td><td>entity / mapper / service / DTO <strong>一行未写</strong></td></tr><tr><td>数据库</td><td>13 张表结构完整：用户域 2、商品域 5、交易域 5、管理 1</td></tr></tbody></table><p>数据库设计要点（实现时必须遵守）：</p><ul><li>无物理外键，关联完整性由应用层保证；</li><li>金额一律 DECIMAL，接口层用字符串传输；</li><li>核心表逻辑删除（<code>deleted</code>），订单/明细/评价创建后不可变；</li><li>订单保存商品、规格、图片、收货地址快照；</li><li>防超卖靠 <code>t_sku.stock &gt;= ?</code> 条件更新 + <code>stock_version</code> 乐观锁；</li><li>唯一约束支撑业务：<code>uk_user_sku</code>（加购累加）、<code>uk_order_item_id</code>（一明细一评价）、<code>uk_order_no</code>/<code>uk_payment_no</code>（幂等）。</li></ul><hr><h3 id="二开工前问题清单阶段-0-必须处理" tabindex="-1">二、开工前问题清单（阶段 0 必须处理） <a class="header-anchor" href="#二开工前问题清单阶段-0-必须处理" aria-label="Permalink to &quot;二、开工前问题清单（阶段 0 必须处理）&quot;">​</a></h3><ol><li>pom 缺 JWT 依赖；application.yml 配了 Redis 但 pom 没有 redis starter（refresh token、Idempotency-Key 幂等都要用）。</li><li>MyBatis-Plus 3.5.9 分页插件已拆分，需额外引入 <code>mybatis-plus-jsqlparser</code>，否则分页插件不生效。</li><li>未配置：分页插件、乐观锁插件、逻辑删除全局映射（<code>deleted</code> 字段）、创建/更新时间自动填充。</li><li>安全层只有路由边界：无 <code>BCryptPasswordEncoder</code>、无 JWT 过滤器、无当前用户上下文，<code>httpBasic</code> 是占位。</li><li><code>GlobalExceptionHandler</code> 吞异常不打日志；<code>AccessDeniedException</code> 会被兜底成 <code>50000</code>（应为 40300），无 40100 映射。</li><li>接口缺口：<code>/categories/tree</code>、<code>/brands</code>、<code>/products/{id}/reviews</code> 无控制器；管理端缺 <code>/admin/auth/login</code>、商品增改、SKU 管理、订单详情、分类管理。</li><li>杂项：README 写 <code>sql/01_schema.sql</code> 实际在 <code>docs/</code>；无种子数据 SQL（管理员账号、示例商品）；openapi.yaml 缺管理端多个路径；AuthController 的 register 复用 LoginRequest（缺 nickname/phone/email）。</li></ol><hr><h3 id="三分阶段实施计划" tabindex="-1">三、分阶段实施计划 <a class="header-anchor" href="#三分阶段实施计划" aria-label="Permalink to &quot;三、分阶段实施计划&quot;">​</a></h3><h4 id="阶段-0基础设施补齐约半天" tabindex="-1">阶段 0：基础设施补齐（约半天） <a class="header-anchor" href="#阶段-0基础设施补齐约半天" aria-label="Permalink to &quot;阶段 0：基础设施补齐（约半天）&quot;">​</a></h4><ul><li>[ ] pom 补依赖：<code>jjwt</code>（0.12.x，api/impl/jackson 三件）、<code>spring-boot-starter-data-redis</code>、<code>mybatis-plus-jsqlparser</code></li><li>[ ] MyBatis-Plus 配置类：<code>PaginationInnerInterceptor</code>（分页）+ <code>OptimisticLockerInnerInterceptor</code>（乐观锁）+ 逻辑删除全局配置 + <code>MetaObjectHandler</code> 时间自动填充</li><li>[ ] application.yml 补 mybatis-plus 逻辑删除映射；确认 Redis 连接可用</li><li>[ ] 安全基础：<code>BCryptPasswordEncoder</code> Bean、JWT 工具类（签发/校验 access + refresh）、<code>JwtAuthenticationFilter</code>、SecurityConfig 接入过滤器并替换 httpBasic 占位</li><li>[ ] 认证失败/无权限返回 40100/40300（AuthenticationEntryPoint + AccessDeniedHandler）</li><li>[ ] <code>CurrentUser</code> 工具：从 SecurityContextHolder 取当前 userId（控制器统一入口）</li><li>[ ] <code>GlobalExceptionHandler</code> 补日志（含 traceId）+ 40100/40300/40400 映射</li><li>[ ] 建 13 张表的 entity（<code>@TableLogic</code>、<code>@Version</code> 注解齐全）+ mapper 骨架</li><li>[ ] 修 README 的 schema 路径；写种子数据 SQL（管理员账号 BCrypt 密码、分类/品牌/商品/SKU 示例）</li><li>[ ] AuthController.register 请求体补 nickname/phone/email 字段</li></ul><p><strong>回归点</strong>：服务能启动连上 MySQL/Redis，公开接口返回统一响应结构，受保护接口未带 Token 返回 40100。</p><h4 id="阶段-1用户与认证约-1-天" tabindex="-1">阶段 1：用户与认证（约 1 天） <a class="header-anchor" href="#阶段-1用户与认证约-1-天" aria-label="Permalink to &quot;阶段 1：用户与认证（约 1 天）&quot;">​</a></h4><ul><li>[x] <code>POST /auth/register</code>：用户名/手机号唯一校验，BCrypt 入库</li><li>[x] <code>POST /auth/login</code>：校验密码与状态，签发 access + refresh token</li><li>[x] <code>POST /auth/refresh</code>：refresh token 换新 access token（Redis 存储校验）</li><li>[x] <code>GET/PUT /users/me</code>：资料读取与修改</li><li>[x] 地址 CRUD：增/改/删/列表（默认地址优先排序）；改删必须校验归属（user_id）</li><li>[x] 新增地址 <code>isDefault=1</code> 时事务内清除旧默认；<code>PUT /addresses/{id}/default</code> 设置默认</li></ul><p><strong>回归点</strong>：注册→登录→带 Token 查资料/地址全链路；用 A 用户 Token 改 B 用户地址返回 40300。</p><h4 id="阶段-2商品浏览约-1-天全公开接口" tabindex="-1">阶段 2：商品浏览（约 1 天，全公开接口） <a class="header-anchor" href="#阶段-2商品浏览约-1-天全公开接口" aria-label="Permalink to &quot;阶段 2：商品浏览（约 1 天，全公开接口）&quot;">​</a></h4><ul><li>[x] <code>GET /categories/tree</code>：启用分类按 <code>parent_id</code> 建三级树</li><li>[x] <code>GET /brands</code>：品牌分页</li><li>[x] <code>GET /products</code>：keyword/categoryId/brandId/minPrice/maxPrice + 5 种排序（default/price_asc/price_desc/sales/newest）；只返回上架未删除；价格用 <code>price_min/price_max</code> 冗余字段</li><li>[x] <code>GET /products/{id}</code>：详情 = SPU + 启用 SKU 列表 + 相册 + 评价摘要（均分/数量）</li><li>[x] <code>GET /products/{id}/reviews</code>：评价分页，按星级筛选，仅显示状态</li></ul><p><strong>回归点</strong>：空库走种子数据能完成分类树 → 商品列表 → 详情 → 评价的浏览链路。</p><h4 id="阶段-3购物车约半天" tabindex="-1">阶段 3：购物车（约半天） <a class="header-anchor" href="#阶段-3购物车约半天" aria-label="Permalink to &quot;阶段 3：购物车（约半天）&quot;">​</a></h4><ul><li>[x] <code>POST /cart/items</code>：同 SKU 已存在则累加数量（依赖 <code>uk_user_sku</code>，用 <code>ON DUPLICATE KEY UPDATE</code> 或先查后改）；校验 SKU 上架且启用</li><li>[x] <code>PUT /cart/items/{id}</code>：改数量/勾选，校验条目归属</li><li>[x] <code>DELETE /cart/items/{id}</code>：删除本人条目</li><li>[x] <code>PUT /cart/items/check-all</code>：批量勾选/取消</li><li>[x] <code>GET /cart</code>：联查 SKU + 商品，实时返回可售状态（下架/禁用/库存不足标记）</li></ul><p><strong>回归点</strong>：同一 SKU 重复加购只有一条记录且数量累加（对应验收项 1）。</p><h4 id="阶段-4订单与支付约-23-天核心难点" tabindex="-1">阶段 4：订单与支付（约 2~3 天，核心难点） <a class="header-anchor" href="#阶段-4订单与支付约-23-天核心难点" aria-label="Permalink to &quot;阶段 4：订单与支付（约 2~3 天，核心难点）&quot;">​</a></h4><p><strong>订单创建（事务，对应验收项 2/4）：</strong></p><ul><li>[x] <code>POST /orders/preview</code>：按地址 + 勾选购物车试算金额，不扣库存</li><li>[x] <code>POST /orders</code>：Idempotency-Key 幂等（Redis 记录首次结果）→ 地址归属校验 → 查 SKU/商品校验上架 → 条件扣库存（<code>stock &gt;= quantity</code>，任一 SKU 失败整单回滚并返回 40900）→ 计算金额（<code>payAmount = totalAmount + freightAmount - discountAmount</code>）→ 写订单 + 明细快照 → 删除已结算购物车条目</li><li>[x] 订单号生成规则（时间戳 + 随机/雪花，满足 <code>uk_order_no</code>）</li></ul><p><strong>订单查询与流转（状态机，对应验收项 6）：</strong></p><ul><li>[ ] <code>GET /orders</code>：我的订单分页，按状态筛选</li><li>[ ] <code>GET /orders/{orderNo}</code>：详情 = 订单 + 明细快照 + 支付信息，校验归属</li><li>[ ] <code>POST /orders/{orderNo}/cancel</code>：仅状态 10，释放库存，写 cancel_time，10→50</li><li>[ ] <code>POST /orders/{orderNo}/confirm</code>：仅状态 30，30→40，写 finish_time</li><li>[ ] 状态流转统一封装，非法流转抛 40900，服务端校验不依赖前端</li></ul><p><strong>支付（对应验收项 3）：</strong></p><ul><li>[ ] <code>POST /orders/{orderNo}/pay</code>：仅状态 10；金额从订单读取不接受客户端值；写 <code>t_payment</code> 流水返回模拟支付参数</li><li>[ ] <code>POST /payments/callback</code>：验签 + 按 <code>paymentNo</code> + 金额校验；成功则支付流水置成功、订单 10→20、写 pay_time、累加商品销量；重复成功回调直接返回成功不重复推进</li><li>[ ] （可选）<code>@Scheduled</code> 定时任务：超时未支付（如 30 分钟）自动取消并释放库存</li></ul><p><strong>回归点</strong>：并发两个请求买最后 1 件只有一单成功；改价后历史订单仍显示快照金额；回调重复投递订单状态不变。</p><h4 id="阶段-5评价约半天" tabindex="-1">阶段 5：评价（约半天） <a class="header-anchor" href="#阶段-5评价约半天" aria-label="Permalink to &quot;阶段 5：评价（约半天）&quot;">​</a></h4><ul><li>[ ] <code>POST /orders/{orderNo}/items/{itemId}/review</code>：校验订单归属 + 订单状态 40 + 明细属于该订单；<code>uk_order_item_id</code> 兜底唯一，重复评价返回 40900</li><li>[ ] 请求字段：rating 1~5、content、images、isAnonymous；评价默认显示状态</li><li>[ ] 商品详情/评价列表接口联动新数据（阶段 2 已留好）</li></ul><p><strong>回归点</strong>：已完成订单明细可评价一次，二次评价被拒。</p><h4 id="阶段-6管理端约-12-天" tabindex="-1">阶段 6：管理端（约 1~2 天） <a class="header-anchor" href="#阶段-6管理端约-12-天" aria-label="Permalink to &quot;阶段 6：管理端（约 1~2 天）&quot;">​</a></h4><ul><li>[ ] <code>POST /admin/auth/login</code>：管理员登录，JWT 加角色 claim（与用户 Token 区分，用户 Token 调管理端返回 40300）</li><li>[ ] 商品管理：<code>GET /admin/products</code> 分页筛选、<code>POST /admin/products</code>（SPU+SKU+相册一个事务，同步算 price_min/max）、<code>PUT /admin/products/{id}</code>、<code>PUT /admin/products/{id}/status</code> 上下架、<code>POST /admin/products/{id}/skus</code>、<code>PUT /admin/skus/{skuId}</code> 改价格/库存/状态</li><li>[ ] 订单管理：<code>GET /admin/orders</code>（状态/订单号/时间筛选）、<code>GET /admin/orders/{orderNo}</code>、<code>POST /admin/orders/{orderNo}/ship</code>（仅状态 20，写 express_company/express_no + delivery_time，20→30）</li><li>[ ] 评价审核：<code>GET /admin/reviews</code>、<code>PUT /admin/reviews/{id}/status</code> 隐藏/显示</li><li>[ ] 分类管理：<code>GET /admin/categories</code>、<code>POST/PUT /admin/categories</code></li><li>[ ] （可选）超级管理员（role=2）管理管理员账号</li></ul><p><strong>回归点</strong>：发货后订单进入已发货且写入了物流与时间字段；用户 Token 访问管理端被拒。</p><h4 id="阶段-7验收与收尾" tabindex="-1">阶段 7：验收与收尾 <a class="header-anchor" href="#阶段-7验收与收尾" aria-label="Permalink to &quot;阶段 7：验收与收尾&quot;">​</a></h4><ul><li>[ ] 单测/集成测试覆盖文档验收清单 6 条（见第四节）</li><li>[ ] 补齐 openapi.yaml 缺失的管理端路径</li><li>[ ] 全链路手工回归：注册 → 浏览 → 加购 → 下单 → 支付 → 发货 → 确认收货 → 评价</li><li>[ ] 清理控制器占位 TODO 与无用代码，统一异常码使用</li></ul><hr><h3 id="四验收清单-阶段对照来自接口文档第-6-节" tabindex="-1">四、验收清单 ↔ 阶段对照（来自接口文档第 6 节） <a class="header-anchor" href="#四验收清单-阶段对照来自接口文档第-6-节" aria-label="Permalink to &quot;四、验收清单 ↔ 阶段对照（来自接口文档第 6 节）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>验收项</th><th>依赖阶段</th></tr></thead><tbody><tr><td>1</td><td>同用户同 SKU 并发加购最终只有一条记录（<code>uk_user_sku</code>）</td><td>阶段 3</td></tr><tr><td>2</td><td>并发购买最后 1 件库存只有一单成功，失败方 40900，无半订单</td><td>阶段 4</td></tr><tr><td>3</td><td>支付回调重复投递不重复改状态、不重复计销量</td><td>阶段 4</td></tr><tr><td>4</td><td>改价/改名/改地址后历史订单仍显示下单快照</td><td>阶段 4</td></tr><tr><td>5</td><td>用户不能读写他人订单/地址/购物车；用户 Token 不能调管理端</td><td>阶段 1/4/6</td></tr><tr><td>6</td><td>状态转换、评价唯一、发货均有服务端校验</td><td>阶段 4/5/6</td></tr></tbody></table><hr><h3 id="五约定与提醒" tabindex="-1">五、约定与提醒 <a class="header-anchor" href="#五约定与提醒" aria-label="Permalink to &quot;五、约定与提醒&quot;">​</a></h3><ul><li>事务、库存扣减、支付验签一律放 service 层，控制器只做参数校验和编排（README 明确要求）。</li><li>客户端传入的 userId、价格、库存、金额全部不可信，一律以服务端查询为准。</li><li>响应不得暴露 <code>password_hash</code>、<code>deleted</code>、<code>stock_version</code> 等内部字段。</li><li>金额接口层用字符串、库内用 DECIMAL；时间格式 <code>yyyy-MM-dd HH:mm:ss</code>。</li><li>所有资源按当前登录用户的 user_id 做数据隔离。</li></ul></div><hr><p><em>原笔记：YukiShopping/实施计划.md。迁移时保留原文结构，完成链接、附件和已识别问题的适配。</em></p>',6)])])}const m=o(l,[["render",c]]);export{p as __pageData,m as default};
